// Creating a custom Promise
let myDataPromise = new Promise(function(resolve, reject) {

  // Simulating a network request that takes 2 seconds
  setTimeout(function() {
    let success = true;

    if (success) {
      resolve('Data successfully fetched!'); // Fulfills the promise
    } else {
      reject('Network Error!'); // Rejects the promise
    }
  }, 2000);

});
console.log('Promise is pending...');

console.log('Waiting for data...');

// We use the Promise we created in the previous topic.
myDataPromise
  .then(function(resultData) {
    // This runs if resolve() was called
    console.log('Success!', resultData);
  })
  .catch(function(errorMessage) {
    // This runs if reject() was called
    console.log('Failed:', errorMessage);
  });

// Simulating a promise that returns user data
