// The modern Async/Await syntax
async function handleLogin() {
  console.log('Logging in...');

  // The code pauses here until fetchProfile() finishes!
  let profileData = await fetchProfile();

  // This line only runs AFTER the promise is resolved
  console.log('User profile loaded:', profileData);
}

handleLogin();

async function getDashboardData() {
  try {
    console.log('Starting data fetch...');

    // Simulating a Promise that rejects (fails)
    let response = await Promise.reject('Server is down!');

    // This line will NEVER run because the promise rejected
    console.log('Data loaded:', response);

  } catch (error) {
    // Execution immediately jumps here
    console.log('An error occurred:', error);
  }
}

getDashboardData();
console.log('Execution continues normally.');

async function getUser() {
  try {
    console.log('Fetching User Data...');

    // 1. Await the network request to the server
    let response = await fetch('https://jsonplaceholder.typicode.com/users/1');

    // 2. Await the conversion of the data into a JS Object
    let data = await response.json();

    // 3. Use the data!
    console.log('User Name:', data.name);
    console.log('Email:', data.email);

  } catch (error) {
    console.log('Failed to fetch:', error);
  }
}
