// Defining the Blueprint (Class)
class BankAccount {
  // The constructor runs automatically when a new object is made
  constructor(ownerName) {
    this.owner = ownerName;
    this.balance = 0;
    console.log('New account created for ' + this.owner);
  }
}

// Creating new Objects (Instances) based on the Class
let account1 = new BankAccount('Alice');
console.log('Balance:', account1.balance);

let account2 = new BankAccount('Bob');
console.log('Balance:', account2.balance);

class BankAccount {
  constructor(ownerName) {
    this.owner = ownerName;
    this.balance = 0;
  }

  // Method to handle deposits
  deposit(amount) {
    this.balance += amount;
    console.log('Deposited:', amount);
  }

  // Method to handle withdrawals
  withdraw(amount) {
    this.balance -= amount;
    console.log('Withdrew:', amount);
  }
}

let myAccount = new BankAccount('Nitesh');

// Using methods instead of changing this.balance directly
myAccount.deposit(100);
console.log('Current Balance:', myAccount.balance);

myAccount.withdraw(40);
console.log('Current Balance:', myAccount.balance);
